<template>
  <AppLoader v-if="isLoading" subject="subcontractor company" />
  <AppError v-else-if="error" :error="error" title="Failed to load subcontractor company" />
  <AppEmpty v-else-if="!data" subject="subcontractor company" />
  <SubcontractorCompanyForm
    v-else
    :initial-values="data"
    :preview-logo-url="data.logo_url"
    :is-saving="isUpdateSubcontractorCompanyLoading"
    submit-label="Save Changes"
    :cancel-to="null"
    guard-unsaved-changes
    disable-submit-when-pristine
    :on-submit="onSubmit"
  />
</template>

<script lang="ts" setup>
import {
  getSubcontractorCompanyEditableFields,
  type GetSubcontractorCompanyEditableFieldsResponse,
  type UpdateSubcontractorCompanyRequest,
} from '~/client';
import type { SubcontractorCompanyFormValues } from '~/constants/validationSchemas/subcontractorCompanyForm';
import { useUpdateSubcontractorCompany } from '~/mutations/subcontractor-company/edit';

definePageMeta({
  roles: ['admin'],
});

const companyId = computed(() => useRoute('subcontractor-companies-id-edit').params.id);

const { data, error, isLoading } = useQuery({
  // Nested under the parent details key so the mutation's prefix invalidation
  // (['subcontractor-company', id]) refetches both, but distinct enough to avoid colliding
  // with the parent details query — this hits the dedicated /edit endpoint, which returns a
  // different (editable-fields-only) shape.
  key: () => ['subcontractor-company', companyId.value, 'edit'],
  query: (): Promise<GetSubcontractorCompanyEditableFieldsResponse> =>
    getSubcontractorCompanyEditableFields({
      composable: '$fetch',
      path: { subcontractor_company_id: companyId.value },
    }),
});

useHead({
  title: () => (data.value?.name ? `Edit ${data.value.name}` : 'Edit Subcontractor Company'),
});

const { updateSubcontractorCompany, isUpdateSubcontractorCompanyLoading } = useUpdateSubcontractorCompany();

const onSubmit = async ({ logo_url, ...rest }: SubcontractorCompanyFormValues) => {
  // Only persist logo_url when it changed: the prefilled value is the existing logo's public URL
  // (must never be saved); a freshly uploaded logo is a private_url.
  const payload: UpdateSubcontractorCompanyRequest = {
    ...rest,
    ...(logo_url !== data.value?.logo_url && { logo_url }),
  };

  await updateSubcontractorCompany({
    subcontractorCompanyId: companyId.value,
    data: payload,
  });
};
</script>
