import { updateSubcontractorCompany as updateSubcontractorCompanyFunc } from '~/client';
import type { UpdateSubcontractorCompanyRequest, UpdateSubcontractorCompanyResponse2 } from '~/client';

export const useUpdateSubcontractorCompany = defineMutation(() => {
  const queryCache = useQueryCache();
  const { mutateAsync, asyncStatus } = useMutation({
    mutation: (params: {
      subcontractorCompanyId: string;
      data: UpdateSubcontractorCompanyRequest;
    }): Promise<UpdateSubcontractorCompanyResponse2> =>
      updateSubcontractorCompanyFunc({
        composable: '$fetch',
        path: { subcontractor_company_id: params.subcontractorCompanyId },
        body: ref(params.data),
      }),
    onSuccess: (_, params) => {
      queryCache.invalidateQueries({ key: ['subcontractor-company', params.subcontractorCompanyId] });
      showToastSuccess('Company updated successfully');
    },
    onError(error) {
      showToastError(error);
    },
  });

  return {
    updateSubcontractorCompany: mutateAsync,
    isUpdateSubcontractorCompanyLoading: computed(() => asyncStatus.value === 'loading'),
  };
});
